package nl.slimov.app;
import org.json.*;
/** Pure geometric progress. No clock-based invented visits or extrapolation. */
public final class WatchLogic {
 public static double distance(double lat,double lon,double a,double b){return Math.hypot((lon-b)*111320*Math.cos(lat*Math.PI/180),(lat-a)*111320);}
 public static JSONObject progress(JSONObject model,JSONObject point,double previous)throws Exception{
  JSONObject out=new JSONObject().put("reliable",false);double timestamp=point.optDouble("timestamp",0),age=System.currentTimeMillis()/1000.0-timestamp;if(!point.optBoolean("positionTimeKnown",true)||age>120||age< -60||timestamp<=0||model.optBoolean("schematic"))return out;
  JSONArray points=model.getJSONArray("points"),cumulative=model.getJSONArray("cumulative"),stops=model.getJSONArray("stops");double lat=point.getDouble("lat"),lon=point.getDouble("lon"),best=Double.MAX_VALUE,along=0;java.util.List<double[]> candidates=new java.util.ArrayList<>();
  for(int i=1;i<points.length();i++){JSONArray a=points.getJSONArray(i-1),b=points.getJSONArray(i);double ax=(a.getDouble(1)-lon)*111320*Math.cos(lat*Math.PI/180),ay=(a.getDouble(0)-lat)*111320,bx=(b.getDouble(1)-lon)*111320*Math.cos(lat*Math.PI/180),by=(b.getDouble(0)-lat)*111320,dx=bx-ax,dy=by-ay,den=dx*dx+dy*dy;if(den<0.01)continue;double f=Math.max(0,Math.min(1,-(ax*dx+ay*dy)/den)),position=cumulative.getDouble(i-1)+f*(cumulative.getDouble(i)-cumulative.getDouble(i-1));if(previous>=0&&position<previous-60)continue;double d=Math.hypot(ax+f*dx,ay+f*dy);candidates.add(new double[]{d,position});if(d<best-1||Math.abs(d-best)<12&&previous>=0&&Math.abs(position-previous)<Math.abs(along-previous)){best=d;along=position;}}
  if(best>180)return out;if(previous<0)for(double[] candidate:candidates)if(candidate[0]<=best+12&&Math.abs(candidate[1]-along)>300)return out;int passed=-1,current=-1,next=-1;for(int i=0;i<stops.length();i++){JSONObject s=stops.getJSONObject(i);if(s.optDouble("along")<along-40)passed=i;if(!s.optBoolean("cancelled")&&Math.abs(s.optDouble("along")-along)<45&&distance(lat,lon,s.getDouble("lat"),s.getDouble("lon"))<55)current=i;}
  if(current>=0)passed=Math.max(passed,current);for(int i=passed+1;i<stops.length();i++)if(!stops.getJSONObject(i).optBoolean("cancelled")){next=i;break;}
  return out.put("reliable",true).put("passed",passed).put("current",current).put("next",next).put("along",along).put("timestamp",timestamp);
 }
 public static boolean cancelled(JSONObject trip,String id){JSONArray legs=trip.optJSONArray("legs");if(legs!=null)for(int i=0;i<legs.length();i++){JSONObject l=legs.optJSONObject(i);if(l!=null&&l.optString("tripId").equals(id)&&l.optBoolean("cancelled"))return true;}return false;}
 public static boolean eventRealtime(JSONObject place,String event){String reason=place.optString(event+"TimestampReason");return reason.equals("OBSERVED")||reason.equals("PREDICTED")||reason.equals("PROPAGATED");}
 public static JSONObject event(JSONObject trip,String tripId,String stopId,String scheduled,String kind){JSONArray legs=trip.optJSONArray("legs");if(legs==null)return null;JSONObject found=null;int matches=0;for(int i=0;i<legs.length();i++){JSONObject l=legs.optJSONObject(i);if(l==null||!l.optString("tripId").equals(tripId))continue;JSONArray ps=new JSONArray();ps.put(l.optJSONObject("from"));JSONArray middle=l.optJSONArray("intermediateStops");if(middle!=null)for(int j=0;j<middle.length();j++)ps.put(middle.opt(j));ps.put(l.optJSONObject("to"));for(int j=0;j<ps.length();j++){JSONObject p=ps.optJSONObject(j);if(p==null||!p.optString("stopId").equals(stopId))continue;matches++;found=p;if(!scheduled.isEmpty()&&scheduled.equals(p.optString(kind.equals("arrival")?"scheduledArrival":"scheduledDeparture")))return p;}}return matches==1&&scheduled.isEmpty()?found:null;}
 public static JSONObject observedProgress(JSONObject model,JSONObject trip,String id,int target)throws Exception{JSONArray stops=model.getJSONArray("stops");int passed=-1;long last=0,now=System.currentTimeMillis();boolean cancelled=cancelled(trip,id);for(int i=0;i<stops.length();i++){JSONObject stop=stops.getJSONObject(i);String stopId=stop.optString("stopId","nl-OpenOV_"+stop.optString("id"));for(String kind:new String[]{"arrival","departure"}){JSONObject e=event(trip,id,stopId,stop.optString(kind.equals("arrival")?"scheduledArrival":"scheduledDeparture"),kind);if(e==null)continue;if(i==target&&e.optBoolean("cancelled"))cancelled=true;if(!e.optString(kind+"TimestampReason").equals("OBSERVED"))continue;try{long time=java.time.Instant.parse(e.getString(kind)).toEpochMilli();if(time<=now&&i>=passed){passed=i;last=time;}}catch(Exception ignored){}}}return new JSONObject().put("passed",passed).put("timestamp",last/1000).put("reliable",last>0&&now-last<=120000).put("cancelled",cancelled);}
}
